    /** [symbol] at weight 700, as Bold Text draws it: the same symbol for one at 700 already. */
    fun bold(symbol: ImageVector): ImageVector = boldVersions[symbol]?.value ?: symbol

    /** The symbol for an SF Symbol's name, as :core gives them; null for one the app doesn't draw. */
    fun named(systemName: String): ImageVector? = when (systemName) {
        "exclamationmark.triangle" -> warning
        "exclamationmark.triangle.fill" -> warningFill
        "moon.fill" -> moonFill
        "calendar" -> calendar
        "scooter" -> scooter
        "clock" -> clock
        "hourglass" -> hourglass
        "map" -> map
        "line.3.horizontal.decrease" -> filter
        "arrow.clockwise" -> refresh
        "xmark" -> close
        "chevron.right" -> chevronRight
        "checkmark" -> check
        "chevron.up.chevron.down" -> unfold
        "ticket.fill" -> ticketFill
        "info.circle" -> info
        "location.fill" -> locationFill
        "location.slash" -> locationSlash
        "figure.walk" -> walk
        "checkmark.circle.fill" -> checkCircleFill
        "questionmark.circle" -> questionCircle
        "mappin.and.ellipse" -> mapPin
        "magnifyingglass" -> search
        "clock.arrow.circlepath" -> history
        "ellipsis.circle" -> ellipsisCircle
        "envelope" -> envelope
        "hand.raised" -> handRaised
        "chevron.left.forwardslash.chevron.right" -> code
        "arrow.up.right" -> arrowUpRight
        "sun.max.fill" -> sunFill
        "exclamationmark.circle.fill" -> exclamationCircleFill
        "circle" -> circle
        "plus" -> plus
        "minus" -> minus
        "xmark.circle.fill" -> clearFill
        "line.3.horizontal.decrease.circle" -> filterCircle
        "line.3.horizontal.decrease.circle.fill" -> filterCircleFill
        else -> null
    }
}

/**
 * [symbol] as the phone's Bold Text has it drawn (UI-187). On an iPhone, Bold Text makes the system font heavier and
 * the SF Symbols drawn in it with it; Android's adds 300 to every weight, which Compose's text follows
 * (Configuration.fontWeightAdjustment). That takes each of SF's weights the app's symbols stand for, regular (400)
 * to bold (700), to 700 or past it, and 700 is the heaviest Material Symbols has: every symbol is drawn at 700.
 */
@Composable
@ReadOnlyComposable
internal fun boldText(symbol: ImageVector): ImageVector {
    val adjustment = LocalConfiguration.current.fontWeightAdjustment
    val bold = adjustment > 0 && adjustment != Configuration.FONT_WEIGHT_ADJUSTMENT_UNDEFINED
    return if (bold) Symbols.bold(symbol) else symbol
}

/** Each symbol's version at weight 700, made the first time Bold Text draws it. */
private val boldVersions: MutableMap<ImageVector, Lazy<ImageVector>> = Collections.synchronizedMap(IdentityHashMap())

/**
 * A Material Symbol's outline, drawn in a 960-unit box whose top is at −960 as Google's files have it, and [bold],
 * the outline at weight 700 of one drawn lighter.
 */
private fun symbol(name: String, pathData: String, bold: String? = null): ImageVector {
    val symbol = outline(name, pathData)
    if (bold != null) boldVersions[symbol] = lazy { outline(name, bold) }
    return symbol
}

private fun outline(name: String, pathData: String): ImageVector =
    ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 960f, viewportHeight = 960f)
        .addGroup(translationY = 960f)
        .addPath(pathData = addPathNodes(pathData), fill = SolidColor(Color.Black))
        .clearGroup()
        .build()

/**
 * A symbol in SF's hierarchical rendering (UI-364): the [disc] at a lower opacity under the [glyph], both in the
 * colour the symbol is drawn in; [boldDisc] and [boldGlyph] are the two at weight 700.
 */
private fun layeredSymbol(
    name: String,
    disc: String,
    glyph: String,
    glyphScale: Float = 1f,
    boldDisc: String,
    boldGlyph: String,
): ImageVector {
    val symbol = layers(name, disc, glyph, glyphScale)
    boldVersions[symbol] = lazy { layers(name, boldDisc, boldGlyph, glyphScale) }
    return symbol
}

private fun layers(name: String, disc: String, glyph: String, glyphScale: Float): ImageVector =
    ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 960f, viewportHeight = 960f)
        .addGroup(translationY = 960f)
        .addPath(pathData = addPathNodes(disc), fill = SolidColor(Color.Black), fillAlpha = HIERARCHICAL_SECONDARY)
        // A glyph of its own, such as `close`'s, made small enough to sit inside the disc.
        .addGroup(scaleX = glyphScale, scaleY = glyphScale, pivotX = 480f, pivotY = -480f)
        .addPath(pathData = addPathNodes(glyph), fill = SolidColor(Color.Black))
        .clearGroup()
        .clearGroup()
        .build()

/** The opacity of a hierarchical symbol's second layer, as ui.md UI-364 measured it. */
private const val HIERARCHICAL_SECONDARY = 0.3f

